document.querySelectorAll('[data-sector-card]').forEach(card=>{const button=card.querySelector('button');const panel=card.querySelector('.sector-details');button.addEventListener('click',()=>{const was=button.getAttribute('aria-expanded')==='true';document.querySelectorAll('[data-sector-card]').forEach(c=>{c.classList.remove('is-open');c.querySelector('button').setAttribute('aria-expanded','false');c.querySelector('.sector-details').hidden=true});if(!was){card.classList.add('is-open');button.setAttribute('aria-expanded','true');panel.hidden=false}})});